Npc npc_create( UInt8 activation_count , UInt32 timeout )
{
    Npc npc =(Npc) vrtc_build( (Vrtc_Func)npc_timeout , sizeof (struct s_Npc ) );
										  	 
	vrtc_update( (Vrtc)npc , timeout );	

	npc->timeout          = timeout          ;	
	
	npc->activation_count = activation_count ; 	
	
	npc->is_active        = FALSE            ;

	npc->is_enable        = FALSE            ;
		
    return npc ;            
}

